import{_ as o,o as a,c as r,S as s}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"前端部署之CDN的那些事情","description":"现在的前端开发主流是 PWA，简而言之就是像 App 一样使用。基于 PWA 技术可以离线访问，并且可以添加程序到菜单里。离线技术使用的是比较成熟的 Service Workers。但是配合 CDN 就有很多不得不注意的事情。","frontmatter":{"title":"前端部署之CDN的那些事情","date":"2020-01-14 22:59","comments":true,"archives":2020,"tags":["frontend"]},"headers":[],"relativePath":"posts/2020-01-14-frontend-deploy/index.md","filePath":"posts/2020/2020-01-14-frontend-deploy.md"}'),t={name:"posts/2020-01-14-frontend-deploy/index.md"};function n(l,e,i,c,p,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<p>现在的前端开发主流是 PWA，简而言之就是像 App 一样使用。基于 PWA 技术可以离线访问，并且可以添加程序到菜单里。离线技术使用的是比较成熟的 Service Workers。但是配合 CDN 就有很多不得不注意的事情。</p><h2 id="cdn-部署静态资源" tabindex="-1">CDN 部署静态资源 <a class="header-anchor" href="#cdn-部署静态资源" aria-label="Permalink to &quot;CDN 部署静态资源&quot;">​</a></h2><p>现代化前端开发主要是把 CSS，JS，图片等静态资源放在 CDN 上有效提高载入速度。把静态 HTML 文件放在服务器上，有利于更新网站最新状态，例如进入维护状态，直接把静态 HTML 文件替换为维护页面即可。</p><h2 id="同源策略问题" tabindex="-1">同源策略问题 <a class="header-anchor" href="#同源策略问题" aria-label="Permalink to &quot;同源策略问题&quot;">​</a></h2><p>正常情况下，资源文件和主网站不在同一个域名下，例如主网站是<code>icehoney.me</code>，资源网站是<code>static.icehoney.me</code>。当然了，资源文件使用 GET 方法浏览器自动载入，没有任何问题。但是注册 Service Worker 的 JS 文件是不能放在 CDN 上的，因为这是官方的规定。个人理解是出于安全因素的考虑。所以我们在主服务器上不仅要放静态的 HTML 文件，还要放一个 serive-worker.js 文件。</p><h2 id="svg-symbol-的使用问题" tabindex="-1">SVG symbol 的使用问题 <a class="header-anchor" href="#svg-symbol-的使用问题" aria-label="Permalink to &quot;SVG symbol 的使用问题&quot;">​</a></h2><p>现在前端的开发针对很多小图标，都是采用 SVG 的方式来引用。其中 SVG symbol 特别好用，可以在页面里嵌入一个 inline 的 SVG，然后在其他对方使用<code>&lt;use&gt;</code>标签来引用。但是对于放在 CDN 上的 SVG 文件，不能直接使用下面的形式：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">use</span><span style="color:#6F42C1;"> xlink</span><span style="color:#24292E;">:</span><span style="color:#6F42C1;">href</span><span style="color:#D73A49;">=</span><span style="color:#032F62;">&quot;https://static.icehoney.me/icon.svg#china&quot;</span><span style="color:#24292E;"> /&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果引用 CDN 的 SVG 浏览器会报错，解决方案是使用<code>svg-inline-loader</code>，手动在 HTML 里面注入 SVG 文件。<code>document.body.insertAdjacentHTML</code> 方法可以注入 inline 的 SVG。</p><h2 id="workbox-配置" tabindex="-1">Workbox 配置 <a class="header-anchor" href="#workbox-配置" aria-label="Permalink to &quot;Workbox 配置&quot;">​</a></h2><p>首先，PWA 项目的路由都是由前端来处理，所以我们需要使用<code>navigateFallback</code>保证不管导航到哪个路由都能映射到缓存的 HTML 文件。然后是使用<code>runtimeCaching</code>配置缓存服务器请求。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>由于 Service Workers 的导入使得 CDN 部署变得有些麻烦，不过这些问题好在都能找到解决方案。还有一点是 Chrome 的 Network 面板里的 offline 模式不能测试 Service Workers 的离线。需要自己手动拔网线才能测试。</p><h2 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h2><p><a href="https://github.com/w3c/ServiceWorker/issues/940" target="_blank" rel="noreferrer">Is it possible to serve service workers from CDN/remote origin?</a></p><p><a href="https://developers.google.com/web/tools/workbox/modules/workbox-webpack-plugin" target="_blank" rel="noreferrer">Workbox webpack Plugins</a></p>',16)])])}const m=o(t,[["render",n]]);export{b as __pageData,m as default};
